const result = errors
  .map((e: ErrorObject) => {
    let field = '';
    const instancePath = (e as any).instancePath ?? (e as any).dataPath ?? '';
    if (instancePath) {
      field = instancePath.replace(/^\//, '');
      field = field.replace(/\//g, '.');
    } else if (e.keyword === 'required' && e.params && 'missingProperty' in e.params) {
      field = (e.params as RequiredParams).missingProperty;
    }
    return `${field ? field + ': ' : ''}${e.message}`;
  })

