const provider: AIProvider = {
  async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
    const messages = params.messages;
    const round = messages.filter(m => m.role === 'assistant').length;
    if (round === 0) {
      yield {type: 'tool_use', toolCall: {id: 'c1', name: 'validate_me', input: {}}};
      yield {type: 'stop', stopReason: 'tool_use'};
      return;
    }

    const last = messages[messages.length - 1];
    const hasToolContent = last.role === 'user' && Array.isArray(last.content);
    if (hasToolContent) {
      const first = last.content[0];
      const isResult = first && 'type' in first && first.type === 'tool_result';
      if (isResult) {
        receivedToolResult = first.content;
      }
    }
    yield {type: 'text', text: 'recovered'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },

